from __future__ import print_function
import filetype
import sys


def guess_file_type():
    """
        Guess the file type based on the provided filename argument.

        Prints the MIME type of the file if successful.

        Raises:
            SystemExit: If the script is not called with exactly one argument.

    """
    if len(sys.argv) != 2:
        print("Usage: taf-file <file_name>", file=sys.stderr)  # noqa: T201
        sys.exit(1)
    expected_mime_type = sys.argv[1]
    for line in sys.stdin:
        file_name = line.rstrip()
        file_type = filetype.guess(file_name)
        if file_type is not None and file_type.mime == expected_mime_type:
            print(file_name)  # noqa: T201
